cd /private/var/folders/tb/68tnh0pn5619ks87wpp1gqmc0000gp/T/ng-facts-atlas-a11y-tool-bcIB8d/workspace/src/app; cat > /private/tmp/claude-502/-private-var-folders-tb-68tnh0pn5619ks87wpp1gqmc0000gp-T-ng-facts-atlas-a11y-tool-bcIB8d-workspace/5a677c11-8965-4c3f-94c9-92d07df2c176/scratchpad/fix.mjs <<'EOF'
import fs from "fs"; import path from "path";
const walk=d=>fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)]);
const verbs={trash:"Remove",flag:"Report",pencil:"Edit",search:"Find",refresh:"Reload",close:"Dismiss",plus:"Add",download:"Export"};
let n=0, seen={};
for(const f of walk(".").filter(f=>/\.(ts|html)$/.test(f))){
  let s=fs.readFileSync(f,"utf8");
  const base=path.basename(f).replace(/\.(page|component)?\.(ts|html)$/,"").replace(/-/g," ");
  const out=s.replace(/<app-icon-button(?=[\s/>])([^>]*?)(\/?>)/gs,(m,attrs,end)=>{
    if(/(^|\s)(\[?label\]?|bind-label|\[attr\.label\])\s*=/.test(attrs)) return m;
    const icon=/\sicon="([^"]+)"/.exec(attrs)?.[1]; const v=verbs[icon];
    if(!v){console.log("UNKNOWN",f,icon);return m;}
    const noun=/\/widgets\//.test(f)||f.startsWith("widgets")?{"tent row":"tent","toolbar":"toolbar item","tent list":"tent","supply table":"supply data"}[base]:base;
    const label=`${v} ${noun}`.replace("Export supply data","Export supply data");
    n++; seen[f]=(seen[f]||0)+1;
    return m.replace(/(\sicon="[^"]+")/,`$1 label="${label}"`);
  });
  if(out!==s) fs.writeFileSync(f,out);
}
console.log(n);
EOF
